using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class GroundUndergroundDetails {
 public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");Physics.SyncTransforms();var text=GameObject.Find("LOGGING RIDGE").transform;var board=GameObject.Find("Logging Ridge sign board").transform;var post=GameObject.Find("Logging Ridge grounded sign post").transform;var delta=-text.forward*8;var foot=post.position-Vector3.up*1.2f+delta;var hits=Physics.RaycastAll(foot+Vector3.up*8,Vector3.down,16,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).OrderBy(h=>Mathf.Abs(h.point.y-foot.y)).ToArray();delta.y=hits[0].point.y-(post.position.y-1.2f);foreach(var t in new[]{text,board,post})t.position+=delta;EditorSceneManager.MarkSceneDirty(text.gameObject.scene);EditorSceneManager.SaveScene(text.gameObject.scene);
 EditorSceneManager.OpenScene("Assets/Scenes/ForestLoopReverse.unity");Physics.SyncTransforms();var root=GameObject.Find("Forest Reverse natural cave atmosphere");int count=0;foreach(var r in root.GetComponentsInChildren<Renderer>().Where(r=>r.name=="Natural cave shoulder outcrop"||r.name=="Cave fallen angular stone")){var p=r.bounds.center;var h=Physics.RaycastAll(p+Vector3.up*3,Vector3.down,8,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).OrderBy(h=>Mathf.Abs(h.point.y-p.y)).First();r.transform.position+=Vector3.up*(h.point.y-r.bounds.min.y+.01f);count++;}
 foreach(var name in new[]{"Fallen cave stone","Cave exposed roots","Storm washed wood","Rat brown grey fur"}){var m=AssetDatabase.LoadAssetAtPath<Material>("Assets/Track/UndergroundPolish/"+name+".mat");m.SetFloat("_Smoothness",0);EditorUtility.SetDirty(m);}EditorSceneManager.MarkSceneDirty(root.scene);EditorSceneManager.SaveScene(root.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/UndergroundPolish/grounding.txt",$"Sign moved before checkpoint upright and post resampled; {count} cave stones seated by renderer base on final terrain. No terrain, trees, routes or collision changed.");EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");return "Final local grounding checked";}
}
